func establishAssociation(conn *net.UDPConn, nodeID string) bool {
	req := message.NewAssociationSetupRequest(
		1,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)

	payload, err := req.Marshal()
	if err != nil {
		log.Printf("[-] Failed to marshal AssociationSetupRequest: %v", err)
		return false
	}

	log.Printf("[*] Sending AssociationSetupRequest...")
	_, err = conn.Write(payload)
	if err != nil {
		log.Printf("[-] Failed to send AssociationSetupRequest: %v", err)
		return false
	}

	conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	buf := make([]byte, 2048)
	n, err := conn.Read(buf)
	if err != nil {
		log.Printf("[-] No AssociationSetupResponse received: %v", err)
		return false
	}

	msg, err := message.Parse(buf[:n])
	if err != nil {
		log.Printf("[-] Failed to parse AssociationSetupResponse: %v", err)
		return false
	}

	if msg.MessageType() == message.MsgTypeAssociationSetupResponse {
		log.Printf("[+] Received AssociationSetupResponse")
		return true
	}

	log.Printf("[-] Unexpected response type: %d", msg.MessageType())
	return false
}

func sendAssociationSetupRequest(conn *net.UDPConn, raddr *net.UDPAddr, nodeID string, seq uint32) error {
	req := message.NewAssociationSetupRequest(
		seq,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)
	payload, err := req.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func sendAssociationSetupResponse(conn *net.UDPConn, raddr *net.UDPAddr, nodeID string, seq uint32) error {
	rsp := message.NewAssociationSetupResponse(
		seq,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewCause(ie.CauseRequestAccepted),
		ie.NewRecoveryTimeStamp(time.Now()),
	)
	payload, err := rsp.Marshal()
	if err != nil {
