func hasBufferedUpdateFAR(req *message.SessionModificationRequest) bool {
	if req == nil {
		return false
	}
	for _, farIE := range req.UpdateFAR {
		if farIE == nil {
			continue
		}
		if farIE.HasBUFF() {
			return true
		}
	}
	return false
}

func sendHeartbeatResponse(conn *net.UDPConn, raddr *net.UDPAddr, seq uint32) error {
	rsp := message.NewHeartbeatResponse(seq, ie.NewRecoveryTimeStamp(time.Now()))
	payload, err := rsp.Marshal()
	if err != nil {
